int n;
int pieces[9][4];
int used[9];
int board[3][3][4]; // store the rotated piece edges for each cell
int total;

// Check if placing piece p with rotation rot at (r,c) is valid
int can_place(int r, int c, int p, int rot) {
    int top = pieces[p][(0 + rot) % 4];
    int right = pieces[p][(1 + rot) % 4];
    int bottom = pieces[p][(2 + rot) % 4];
    int left = pieces[p][(3 + rot) % 4];

    if (r > 0) {
        int above_bottom = board[r-1][c][2];
        if (top != above_bottom) return 0;
    }
    if (c > 0) {
        int left_right = board[r][c-1][1];
        if (left != left_right) return 0;
    }
    // store temporarily for checking
    board[r][c][0] = top;
    board[r][c][1] = right;
    board[r][c][2] = bottom;
    board[r][c][3] = left;
    return 1;
}

