    if (pos == 9) {
        total++;
        return;
    }
    int r = pos / 3;
    int c = pos % 3;

    for (int i = 0; i < 9; i++) {
        if (used[i]) continue;
        used[i] = 1;
        for (int rot = 0; rot < 4; rot++) {
            if (can_place(r, c, i, rot)) {
