int count;

// rotate: new top = old left, new right = old top, new bottom = old right, new left = old bottom
// Actually rotation 90 CW: top=left, right=top, bottom=right, left=bottom
void getRotation(int piece, int rot, int *edges) {
    // rot=0: original, rot=1: 90CW, rot=2: 180, rot=3: 270CW
    for (int i = 0; i < 4; i++) {
        edges[i] = pieces[piece][(i + rot) % 4]; // Wait, need to think carefully
    }
    // Actually for CW rotation: new[0]=old[3], new[1]=old[0], new[2]=old[1], new[3]=old[2]
    // i.e., edges[(i+1)%4] = pieces[piece][i] => edges[i] = pieces[piece][(i+3)%4]
    for (int i = 0; i < 4; i++) {
        edges[i] = pieces[piece][(i + 4 - rot) % 4];
    }
}

void solve(int pos) {
    if (pos == 9) {
        count++;
        return;
    }
    int row = pos / 3, col = pos % 3;
    for (int p = 0; p < 9; p++) {
        if (used[p]) continue;
        for (int r = 0; r < 4; r++) {
            int edges[4];
            getRotation(p, r, edges);
            // edges: top=0, right=1, bottom=2, left=3
            // Check top neighbor
            if (row > 0 && grid[pos-3][2] != edges[0]) continue;
            // Check left neighbor
            if (col > 0 && grid[pos-1][1] != edges[3]) continue;
            used[p] = 1;
            memcpy(grid[pos], edges, 4 * sizeof(int));
            solve(pos + 1);
            used[p] = 0;
        }
    }
}

