#include <stdio.h>
#include <string.h>

#define NPIECES 9
#define NSYM 8

/*
We model each piece by 4 edge symbols in clockwise order:
0 = top, 1 = right, 2 = bottom, 3 = left

A placement is on a 3x3 board, positions:
0 1 2
3 4 5
6 7 8

Pieces may be rotated, not flipped.

The puzzle specifies required unordered symbol pairs on each internal adjacency:
Horizontal:
(0,1), (1,2), (3,4), (4,5), (6,7), (7,8)
Vertical:
(0,3), (1,4), (2,5), (3,6), (4,7), (5,8)

For each such adjacency, the touching symbols must be exactly the given pair
in either order.

Input format assumed:
Multiple test cases.
Each test case consists of 9 lines, one per piece, each line containing 4 symbols.
Symbols are integers 0..7.
A line starting with -1 ends input.

For each test case output the number of solutions.
*/

static int piece[NPIECES][4];
static int used[NPIECES];
static long long ans;

/* required pair for each adjacency, stored as sorted pair */
static int hreq[6][2];
static int vreq[6][2];

static int pos_piece[NPIECES];
static int pos_rot[NPIECES];

static int min2(int a, int b) { return a < b ? a : b; }
static int max2(int a, int b) { return a > b ? a : b; }

static int edge_of(int p, int rot, int side) {
    /* side after rotation rot clockwise */
    return piece[p][(side - rot + 4) & 3];
}

static int pair_match(int a, int b, int req0, int req1) {
    int x = min2(a, b), y = max2(a, b);
    return x == req0 && y == req1;
}

static int check_partial(int pos) {
    int r = pos / 3, c = pos % 3;
    int p = pos_piece[pos];
    int rot = pos_rot[pos];

    /* check left adjacency if exists */
    if (c > 0) {
        int q = pos_piece[pos - 1];
        int qrot = pos_rot[pos - 1];
        int a = edge_of(q, qrot, 1); /* right of left piece */
        int b = edge_of(p, rot, 3);  /* left of current piece */
        int idx = r * 2 + (c - 1);
        if (!pair_match(a, b, hreq[idx][0], hreq[idx][1])) return 0;
    }

    /* check upper adjacency if exists */
    if (r > 0) {
        int q = pos_piece[pos - 3];
        int qrot = pos_rot[pos - 3];
        int a = edge_of(q, qrot, 2); /* bottom of upper piece */
        int b = edge_of(p, rot, 0);  /* top of current piece */
        int idx = c + (r - 1) * 3;
        if (!pair_match(a, b, vreq[idx][0], vreq[idx][1])) return 0;
    }

    return 1;
}

static void dfs(int pos) {
    if (pos == NPIECES) {
        ans++;
        return;
    }

    for (int p = 0; p < NPIECES; p++) {
        if (used[p]) continue;
        used[p] = 1;
        pos_piece[pos] = p;

        for (int rot = 0; rot < 4; rot++) {
            pos_rot[pos] = rot;
            if (check_partial(pos)) dfs(pos + 1);
        }

        used[p] = 0;
    }
}

int main(void) {
    while (1) {
        int first;
        if (scanf("%d", &first) != 1) return 0;
        if (first == -1) break;

        piece[0][0] = first;
        for (int j = 1; j < 4; j++) scanf("%d", &piece[0][j]);
        for (int i = 1; i < NPIECES; i++) {
            for (int j = 0; j < 4; j++) scanf("%d", &piece[i][j]);
        }

        for (int i = 0; i < 6; i++) {
            int a, b;
            scanf("%d %d", &a, &b);
            hreq[i][0] = min2(a, b);
            hreq[i][1] = max2(a, b);
        }
        for (int i = 0; i < 6; i++) {
            int a, b;
            scanf("%d %d", &a, &b);
            vreq[i][0] = min2(a, b);
            vreq[i][1] = max2(a, b);
        }

        memset(used, 0, sizeof(used));
        ans = 0;
        dfs(0);
        printf("%lld\n", ans);
    }

    return 0;
}

