# Symbols:
# A, C, D, E, H, I, J, L  -> map to 0..7
sym_id = {'A': 0, 'C': 1, 'D': 2, 'E': 3, 'H': 4, 'I': 5, 'J': 6, 'L': 7}

# Required adjacent pairs (unordered):
# AC, AH, DE, DJ, EI, HJ, IL, LC
allowed_pairs = {
    frozenset((sym_id['A'], sym_id['C'])),
    frozenset((sym_id['A'], sym_id['H'])),
    frozenset((sym_id['D'], sym_id['E'])),
    frozenset((sym_id['D'], sym_id['J'])),
    frozenset((sym_id['E'], sym_id['I'])),
    frozenset((sym_id['H'], sym_id['J'])),
    frozenset((sym_id['I'], sym_id['L'])),
    frozenset((sym_id['L'], sym_id['C'])),
}

def ok(a, b):
    return frozenset((a, b)) in allowed_pairs

def rotate(piece, r):
    # piece = (top,right,bottom,left), rotate clockwise r times
    t, rr, b, l = piece
    if r == 0:
        return (t, rr, b, l)
    elif r == 1:
        return (l, t, rr, b)
    elif r == 2:
        return (b, l, t, rr)
    else:
        return (rr, b, l, t)

def solve_case(pieces):
    # Precompute all 4 rotations for each piece
    rots = [[rotate(p, r) for r in range(4)] for p in pieces]

    # Board positions:
    # 0 1 2
    # 3 4 5
    # 6 7 8
    #
    # We only need adjacency checks to already-filled neighbors:
    # left and up
    used = [False] * 9
    board = [None] * 9  # stores oriented piece tuples

    # To reduce symmetric overcount by global rotation, fix piece 0 at position 0 with rotation 0.
    # Final answer multiplied by 4, as guaranteed.
    used[0] = True
    board[0] = rots[0][0]

    # Order of filling after position 0
    order = [1, 2, 3, 4, 5, 6, 7, 8]

    def fits(pos, piece):
        t, r, b, l = piece
        row, col = divmod(pos, 3)

        if col > 0:
            left_piece = board[pos - 1]
            if not ok(left_piece[1], l):
                return False
        if row > 0:
            up_piece = board[pos - 3]
            if not ok(up_piece[2], t):
                return False
        return True

    ans = 0

    def dfs(idx):
        nonlocal ans
        if idx == len(order):
            ans += 1
            return

        pos = order[idx]
        for i in range(1, 9):  # piece 0 already fixed
            if not used[i]:
                used[i] = True
                for p in rots[i]:
                    if fits(pos, p):
                        board[pos] = p
                        dfs(idx + 1)
                used[i] = False

    dfs(0)
    return ans * 4

def parse_piece(line):
    s = ''.join(line.split())
    return tuple(sym_id[ch] for ch in s[:4])

def main():
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip() != '']
    if not lines:
        return

    ptr = 0
    out = []

    # Support both formats:
    # 1) first line is T, followed by 9*T lines
    # 2) input is just groups of 9 lines until EOF
    if lines[0].isdigit():
        t = int(lines[0])
        ptr = 1
        for _ in range(t):
            pieces = [parse_piece(lines[ptr + i]) for i in range(9)]
            ptr += 9
            out.append(str(solve_case(pieces)))
    else:
        while ptr + 9 <= len(lines):
            pieces = [parse_piece(lines[ptr + i]) for i in range(9)]
            ptr += 9
            out.append(str(solve_case(pieces)))

    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    main()

