#include <bits/stdc++.h>
using namespace std;

/*
We have 9 square tiles, each with 4 symbols on edges.
Tiles may be rotated, not flipped.

A valid 3x3 arrangement requires every adjacent pair to match one of
the allowed unordered symbol pairs.

Input format (classic "Jigsaw Puzzle" style):
For each puzzle:
- 9 lines: each tile as 4 symbols (characters), in order N E S W
- 12 lines: allowed adjacent pairs, each as 2 symbols
Multiple puzzles until EOF.

Output:
"The number of solutions is X."
for each puzzle.

Because rotating a whole solved board gives 4 solutions, answer is always multiple of 4.
We count all placements/orientations directly.

Approach:
- Encode symbols among 8 possible chars seen in the puzzle.
- allowed[a][b] = allowed[b][a] = true
- Precompute each tile's 4 rotations.
- Backtracking over 9 positions row-major.
  For position p:
    need match with left neighbor if col>0
    need match with upper neighbor if row>0
- Use unused-mask for tiles.

This is small enough: 9! * 4^9 in worst case, but adjacency pruning is strong.
*/

struct RotTile {
    int e[4]; // 0=N,1=E,2=S,3=W
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        vector<string> tileStr(9);
        for (int i = 0; i < 9; ++i) {
            if (!(cin >> tileStr[i])) return 0;
        }

        vector<string> pairs(12);
        for (int i = 0; i < 12; ++i) cin >> pairs[i];

        // Map symbols to 0..7
        map<char,int> id;
        auto getId = [&](char c) -> int {
            auto it = id.find(c);
            if (it != id.end()) return it->second;
            int v = (int)id.size();
            id[c] = v;
            return v;
        };

        for (auto &s : tileStr) for (char c : s) getId(c);
        for (auto &s : pairs) for (char c : s) getId(c);

        int K = id.size();
        vector<vector<bool>> ok(K, vector<bool>(K, false));
        for (auto &s : pairs) {
            int a = getId(s[0]), b = getId(s[1]);
            ok[a][b] = ok[b][a] = true;
        }

        vector<array<RotTile,4>> rot(9);
        for (int i = 0; i < 9; ++i) {
            RotTile base;
            for (int d = 0; d < 4; ++d) base.e[d] = getId(tileStr[i][d]);
            rot[i][0] = base;
            for (int r = 1; r < 4; ++r) {
                // rotate clockwise: new N<-W, E<-N, S<-E, W<-S
                rot[i][r].e[0] = rot[i][r-1].e[3];
                rot[i][r].e[1] = rot[i][r-1].e[0];
                rot[i][r].e[2] = rot[i][r-1].e[1];
                rot[i][r].e[3] = rot[i][r-1].e[2];
            }
        }

        struct Placed {
            int tile, r;
        };
        Placed board[9];
        long long ans = 0;

        function<void(int,int)> dfs = [&](int pos, int usedMask) {
            if (pos == 9) {
                ++ans;
                return;
            }

            int row = pos / 3, col = pos % 3;

            for (int t = 0; t < 9; ++t) {
                if (usedMask & (1 << t)) continue;
                for (int r = 0; r < 4; ++r) {
                    const auto &cur = rot[t][r];
                    bool good = true;

                    if (col > 0) {
                        const auto &L = rot[board[pos - 1].tile][board[pos - 1].r];
                        if (!ok[L.e[1]][cur.e[3]]) good = false; // left E with current W
                    }
                    if (good && row > 0) {
                        const auto &U = rot[board[pos - 3].tile][board[pos - 3].r];
                        if (!ok[U.e[2]][cur.e[0]]) good = false; // up S with current N
                    }

                    if (!good) continue;
                    board[pos] = {t, r};
                    dfs(pos + 1, usedMask | (1 << t));
                }
            }
        };

        dfs(0, 0);

        cout << "The number of solutions is " << ans << ".\n";
    }

    return 0;
}

import java.util.*;

public class JigsawPuzzleSolver {
    static int count;
    static int[] used;
    static int[][] pieces; // 9 x 4: top, right, bottom, left
    static int[][] board;  // 3x3 placement indices

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            pieces = new int[9][4];
            for (int i = 0; i < 9; i++) {
                for (int j = 0; j < 4; j++) {
                    pieces[i][j] = sc.nextInt();
                }
            }
            count = 0;
            used = new int[9];
            board = new int[3][3];
            backtrack(0);
            // Each solution counted 4 times due to board rotation
            System.out.println(count / 4);
        }
        sc.close();
    }

    static void backtrack(int pos) {
        if (pos == 9) {
            count++;
            return;
        }
        int r = pos / 3;
        int c = pos % 3;
        for (int p = 0; p < 9; p++) {
            if (used[p] == 1) continue;
            used[p] = 1;
            for (int rot = 0; rot < 4; rot++) {
                int top = pieces[p][rot];
                int right = pieces[p][(rot + 1) % 4];
                int bottom = pieces[p][(rot + 2) % 4];
                int left = pieces[p][(rot + 3) % 4];
                if (c > 0) {
                    int leftNeighborIdx = board[r][c - 1];
                    int leftNeighborRight = pieces[leftNeighborIdx][(1 + rotationOf(leftNeighborIdx, board, r, c - 1)) % 4];
                    if (left != leftNeighborRight) continue;
                }
                if (r > 0) {
                    int topNeighborIdx = board[r - 1][c];
                    int topNeighborBottom = pieces[topNeighborIdx][(2 + rotationOf(topNeighborIdx, board, r - 1, c)) % 4];
                    if (top != topNeighborBottom) continue;
                }
                board[r][c] = p;
                // store rotation info via piece index in board is enough; we also need rotation amount
                // We'll store rotation in separate array
                rotationStore[r][c] = rot;
                backtrack(pos + 1);
            }
            used[p] = 0;
        }
    }

    static int[][] rotationStore = new int[3][3];

    static int rotationOf(int pieceIdx, int[][] board, int r, int c) {
        // Find rotation stored
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == pieceIdx) return rotationStore[i][j];
            }
        }
        return 0;
    }
}

