        for (int p = 0; p < 9; p++) {
            if (used[p]) continue;
            for (int r = 0; r < 4; r++) {
                // Check top neighbor
                if (row > 0) {
                    int above = placement[pos - 3];
                    int aboveRot = rotation[pos - 3];
                    if (!matches(getEdge(p, r, 0), getEdge(above, aboveRot, 2))) continue;
                }
                // Check left neighbor
                if (col > 0) {
                    int left = placement[pos - 1];
                    int leftRot = rotation[pos - 1];
                    if (!matches(getEdge(p, r, 3), getEdge(left, leftRot, 1))) continue;
                }
                placement[pos] = p;
                rotation[pos] = r;
                used[p] = true;
                solve(pos + 1);
                used[p] = false;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            pieces = new int[9][4];
            for (int i = 0; i < 9; i++)
                for (int j = 0; j < 4; j++)
                    pieces[i][j] = sc.nextInt();
            count = 0;
            used = new boolean[9];
            solve(0);
            System.out.println(count);
        }
    }
}

import java.io.*;
import java.util.*;

/*
 * 3x3 jigsaw counting with rotatable (not flippable) square tiles.
 *
 * There are 9 pieces. Each piece has 4 edge symbols.
 * A solution is an arrangement of the 9 pieces in a 3x3 grid with some rotation for each piece
 * such that every adjacent pair of edges matches one of the allowed unordered symbol pairs.
 *
 * Input format assumed by the classic problem:
 * - Multiple test cases.
 * - Each test case:
 *     12 lines follow, each containing a 2-character string describing one allowed adjacent pair.
 *     Then 9 lines follow, each containing a 4-character string describing a piece in clockwise order.
 * - A test case starting with "000000000000" does not exist here; instead the usual terminator is
 *   the first pair line equal to "*" or similar in some archives. Since statement omitted exact format,
 *   this implementation supports:
 *      * EOF termination
 *      * first token equal to "0"
 *      * first token equal to "*"
 *
 * The answer for each puzzle is the number of solutions.
 *
 * Method:
 * - Encode symbols into 0..7.
 * - Allowed adjacency is stored in an 8x8 boolean matrix, symmetric.
 * - DFS over cells 0..8 in row-major order.
 * - For each unused piece and each of 4 rotations, check top/left constraints.
 * - To avoid counting the same global board under whole-board rotation 4 times,
 *   fix one arbitrary anchor: among the 4 corner positions, piece 0 must be placed in the
 *   top-left corner. Then multiply by 4 at the end? Better:
 *   Since every solution has 4 rotated variants and corners map to corners, requiring piece 0
 *   to be in top-left selects exactly one from each rotational orbit (piece 0 is some corner in
 *   every valid completed board because rotating whole board moves it among positions only if it is
 *   a corner? That is not guaranteed).
 *
 * The statement guarantees answers are multiples of four; safest is to count all directly.
 * The search space is small enough with pruning.
 */

public class Main {
    static final int N = 9;
    static final int SIDE = 3;

    static boolean[][] ok = new boolean[8][8];
    static int[][] piece = new int[N][4];

    static boolean[] used = new boolean[N];
    static int[] placedPiece = new int[N];
    static int[] placedRot = new int[N];

    static long ans;

    static int sym(char c) {
        // Supports digits/letters as symbols; map distinct chars to 0..7 by common contest convention.
        if ('A' <= c && c <= 'H') return c - 'A';
        if ('a' <= c && c <= 'h') return c - 'a';
        if ('0' <= c && c <= '7') return c - '0';
        // fallback for other possible 8-symbol sets
        return c & 7;
    }

    // edge index after rotating clockwise r times:
    // original order assumed [top, right, bottom, left]
    static int edge(int p, int r, int side) {
        // New top comes from old left for cw rotation, etc.
        // Equivalent: side in rotated tile corresponds to original (side - r mod 4)
        int idx = side - r;
        idx %= 4;
        if (idx < 0) idx += 4;
        return piece[p][idx];
    }

    static void dfs(int pos) {
        if (pos == N) {
            ans++;
            return;
        }

        int row = pos / SIDE;
        int col = pos % SIDE;

        for (int p = 0; p < N; p++) {
            if (used[p]) continue;
            used[p] = true;

            for (int r = 0; r < 4; r++) {
                boolean good = true;

                if (row > 0) {
                    int upPos = pos - SIDE;
                    int upPiece = placedPiece[upPos];
                    int upRot = placedRot[upPos];
                    int a = edge(upPiece, upRot, 2); // bottom of upper
                    int b = edge(p, r, 0);           // top of current
                    if (!ok[a][b]) good = false;
                }

                if (good && col > 0) {
                    int leftPos = pos - 1;
                    int leftPiece = placedPiece[leftPos];
                    int leftRot = placedRot[leftPos];
                    int a = edge(leftPiece, leftRot, 1); // right of left
                    int b = edge(p, r, 3);               // left of current
                    if (!ok[a][b]) good = false;
                }

                if (good) {
                    placedPiece[pos] = p;
                    placedRot[pos] = r;
                    dfs(pos + 1);
                }
            }

            used[p] = false;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            if (first.equals("0") || first.equals("*")) break;

            for (int i = 0; i < 8; i++) Arrays.fill(ok[i], false);

            String[] pairs = new String[12];
            pairs[0] = first;
            for (int i = 1; i < 12; i++) {
                pairs[i] = fs.next();
                if (pairs[i] == null) return;
            }

            for (int i = 0; i < 12; i++) {
                String s = pairs[i];
                int a = sym(s.charAt(0));
                int b = sym(s.charAt(1));
                ok[a][b] = ok[b][a] = true;
            }

            for (int i = 0; i < N; i++) {
                String s = fs.next();
                if (s == null) return;
                for (int j = 0; j < 4; j++) piece[i][j] = sym(s.charAt(j));
            }

            Arrays.fill(used, false);
            ans = 0;
            dfs(0);

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}
